function dashboardMarkup(){return `<section class="reference-dashboard"><div class="task-pane"><header><button class="back-button">‹</button><div><span class="folder">▰</span><strong>Farm activity</strong></div><button class="more-button">•••</button></header><label class="task-search">⌕ <input id="task-filter" placeholder="Search farm records..."/><button type="button">⚙</button></label><div class="task-group"><div class="group-title"><span>⌄ &nbsp;📌 Farm records</span><small>2</small></div><article data-view="Livestock"><i class="check red"></i><div><strong>Livestock health</strong><p id="livestock-summary">Loading livestock records…</p><span>#Animal-health</span></div><time>Open</time></article><article data-view="Crops"><i class="check amber"></i><div><strong>Growing crops</strong><p id="crop-summary">Loading field records…</p><span>#Crop-protection</span></div><time>Open</time></article></div><div class="task-group"><div class="group-title"><span>⌄ &nbsp; Live information</span><small>3</small></div><article data-view="Settings"><i class="check green"></i><div><strong>Farm settings</strong><p>Update profile and farm coordinates</p><span>#Farm</span></div><time>Open</time></article><article data-home="true"><i class="check blue"></i><div><strong>Market prices</strong><p id="market-summary">Loading market information…</p><span>#Market</span></div><time>Live</time></article><article><i class="check purple"></i><div><strong>Weather outlook</strong><p id="weather-summary">Loading local weather…</p><span>#Planning</span></div><time>Now</time></article></div><button class="collapsed-group" data-view="Alerts">› &nbsp; Alerts <small id="alert-count">0</small></button><button class="collapsed-group" data-view="Reports">› &nbsp; Reports</button></div><div class="farm-map-pane"><div class="map-toolbar"><button type="button">◇ Farm view</button><label>⌕ <input placeholder="Find records..."/></label><button type="button">⛶</button></div><div class="map-weather"><b id="map-temperature">Weather…</b><span id="map-wind">Connecting</span></div><button class="map-pin pin-one" data-view="Livestock">✓</button><button class="map-pin pin-two amber" data-view="Crops">⌛</button><button class="map-pin pin-three blue" data-view="Alerts">◉</button><button class="map-pin pin-four" data-view="Livestock">✓</button><button class="map-pin pin-five amber" data-view="Crops">⌛</button><div class="map-zoom"><button id="map-reset">⌖</button><button id="map-plus">＋</button><button id="map-minus">−</button></div></div></section>`}

let navigationInProgress=false
function releaseDashboard(){navigationInProgress=true;const workspace=document.querySelector('.app-shell .workspace');workspace?.querySelector('.reference-dashboard')?.remove();workspace?.classList.remove('reference-active');setTimeout(()=>{navigationInProgress=false;sync()},250)}
function openView(label){const button=[...document.querySelectorAll('.app-shell aside nav button')].find(item=>item.textContent.includes(label));releaseDashboard();setTimeout(()=>button?.click(),0)}
async function getApi(path,token){const response=await fetch(`/api/v1${path}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error(`Request failed (${response.status})`);return response.json()}

async function hydrate(workspace){let session;try{session=JSON.parse(sessionStorage.getItem('agrinexus.session')||'null')}catch{return}const token=session?.accessToken;const farmId=document.querySelector('.farm-switcher select')?.value;if(!token||!farmId)return;
workspace.querySelectorAll('[data-view]').forEach(item=>item.addEventListener('click',()=>openView(item.dataset.view)));workspace.querySelector('[data-home]')?.addEventListener('click',async()=>{const prices=await getApi('/market-prices',token);alert(prices.map(item=>`${item.commodity}: R ${item.priceZar} / ${item.unit}`).join('\n'))});const filter=workspace.querySelector('#task-filter');filter?.addEventListener('input',()=>workspace.querySelectorAll('.task-group article').forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(filter.value.toLowerCase())}));
workspace.querySelector('.back-button')?.addEventListener('click',()=>history.back());workspace.querySelector('.more-button')?.addEventListener('click',()=>workspace.querySelectorAll('.collapsed-group').forEach(item=>item.hidden=!item.hidden));const layerButton=workspace.querySelector('.map-toolbar button');layerButton?.addEventListener('click',()=>workspace.querySelector('.farm-map-pane').classList.toggle('map-muted'));const fullscreenButton=workspace.querySelector('.map-toolbar button:last-child');fullscreenButton?.addEventListener('click',()=>workspace.querySelector('.farm-map-pane').requestFullscreen?.());
const map=workspace.querySelector('.farm-map-pane');let zoom=100;const setZoom=value=>{zoom=Math.max(100,Math.min(180,value));map.style.backgroundSize=`${zoom}%`};workspace.querySelector('#map-plus')?.addEventListener('click',()=>setZoom(zoom+15));workspace.querySelector('#map-minus')?.addEventListener('click',()=>setZoom(zoom-15));workspace.querySelector('#map-reset')?.addEventListener('click',()=>setZoom(100));
try{const[dashboard,animals,fields,prices]=await Promise.all([getApi(`/farms/${farmId}/dashboard`,token),getApi(`/farms/${farmId}/animals`,token),getApi(`/farms/${farmId}/fields`,token),getApi('/market-prices',token)]);workspace.querySelector('#livestock-summary').textContent=`${animals.length} animal record${animals.length===1?'':'s'}`;workspace.querySelector('#crop-summary').textContent=`${fields.length} registered field${fields.length===1?'':'s'}`;workspace.querySelector('#market-summary').textContent=`${prices.length} current commodity prices`;workspace.querySelector('#alert-count').textContent=dashboard.unreadNotifications;const weather=dashboard.weather;const updated=weather.retrievedAt?new Date(weather.retrievedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';workspace.querySelector('#map-temperature').textContent=weather.available?`☀ ${Math.round(weather.temperatureC)}°C`:'Weather unavailable';workspace.querySelector('#map-wind').textContent=weather.available?`≋ ${weather.windSpeedKph??0} km/h · Live ${updated}`:weather.message;workspace.querySelector('#weather-summary').textContent=weather.available?`${weather.location} · ${Math.round(weather.temperatureC)}°C · ${weather.rainProbability??0}% rain · updated ${updated}`:weather.message}catch(error){workspace.querySelector('#map-temperature').textContent='API unavailable';workspace.querySelector('#map-wind').textContent=error.message}}

function sync(){if(navigationInProgress)return;const workspace=document.querySelector('.app-shell .workspace');if(!workspace)return;const dashboard=workspace.querySelector('.page-heading h2')?.textContent?.trim()==='Dashboard';workspace.classList.toggle('reference-active',dashboard);if(dashboard&&!workspace.querySelector('.reference-dashboard')){workspace.insertAdjacentHTML('afterbegin',dashboardMarkup());hydrate(workspace)}}document.addEventListener('click',event=>{if(event.target.closest('.app-shell aside nav button'))releaseDashboard();const headerButton=event.target.closest('.app-shell>header button');if(!headerButton)return;if(headerButton.classList.contains('user-menu'))openView('Settings');else if(headerButton.textContent.includes('🔔'))openView('Alerts');else if(headerButton.classList.contains('header-icon'))openView('Livestock')},true);const observer=new MutationObserver(sync);observer.observe(document.body,{childList:true,subtree:true});sync()
